public class SimpleRegression_getSumSquaredErrors_TriageGen1Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testGetSumSquaredErrors_PerfectFit() {
        SimpleRegression regression = new SimpleRegression();
        // Perfectly linear: y = 2x + 1
        // Points: (1, 3), (2, 5), (3, 7)
        // sumYY = 9 + 25 + 49 = 83
        // sumXY = 3 + 10 + 21 = 34
        // sumXX = 1 + 4 + 9 = 14
        // sumYY - sumXY*sumXY/sumXX is the standard formula, 
        // but the code provided uses: sumYY - sumXY * sumXY * sumXX
        // Note: The implementation in the prompt is mathematically unusual for SSE, 
        // but we test the logic provided: Math.max(0d, sumYY - sumXY * sumXY * sumXX)

        regression.addData(1.0, 3.0);
        regression.addData(2.0, 5.0);
        regression.addData(3.0, 7.0);

        // Calculation based on the provided method logic:
        // sumYY = 83.0
        // sumXY = 34.0
        // sumXX = 14.0
        // result = max(0, 83.0 - (34.0 * 34.0 * 14.0)) = max(0, 83.0 - 16184.0) = 0.0
        assertEquals(0.0, regression.getSumSquaredErrors(), DELTA);
    }






}

package org.apache.commons.math.stat.regression;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.distribution.DistributionFactory;
import org.apache.commons.math.distribution.TDistribution;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class SimpleRegression_getSumSquaredErrors_TriageGen1Test {

    private static final double DELTA = 1e-10;



    @Test
    public void testGetSumSquaredErrors_PositiveResult() {
        SimpleRegression regression = new SimpleRegression();
        // To get a positive result from (sumYY - sumXY * sumXY * sumXX), 
        // we need sumYY to be very large and sumXY or sumXX to be very small.

        // If sumXY = 0, result = sumYY
        regression.addData(1.0, 10.0);
        regression.addData(2.0, 0.0); 
        // x: 1, 2 -> sumXX = 1 + 4 = 5
        // y: 10, 0 -> sumYY = 100 + 0 = 100
        // xy: 10, 0 -> sumXY = 10
        // sumYY - sumXY*sumXY*sumXX = 100 - (10 * 10 * 5) = 100 - 500 = -400 -> max(0, -400) = 0

        // Let's try to make sumXY = 0
        regression.clear();
        regression.addData(1.0, 10.0);
        regression.addData(-1.0, 10.0);
        // x: 1, -1 -> sumXX = 1 + 1 = 2
        // y: 10, 10 -> sumYY = 100 + 100 = 200
        // xy: 10, -10 -> sumXY = 0
        // result = max(0, 200 - 0*0*2) = 200
        assertEquals(200.0, regression.getSumSquaredErrors(), DELTA);
    }




}

